// src/icons/packs/emoji.ts
var index = null;
var emojiPack = {
  id: "emoji",
  kind: "glyph",
  labelKey: "iconPicker.emoji",
  descriptionKey: "iconPicker.descEmoji",
  emblemIcon: "smile",
  searchPlaceholderKey: "iconPicker.searchEmoji",
  hasCategories: false,
  variants: [{ kind: "skin-tone" }],
  attribution: {
    title: "Emoji",
    homepage: "https://github.com/milesj/emojibase",
    version: "emojibase",
    licenses: [
      {
        name: "MIT License",
        spdx: "MIT",
        url: "https://github.com/milesj/emojibase/blob/master/LICENSE",
        holder: "Miles Johnson",
        scope: "emoji names and search keywords"
      }
    ],
    modifications: "Names, keywords and skin-tone variants extracted from emojibase-data; the glyphs themselves are rendered by the reader's system emoji font."
  },
  loadIndex() {
    if (!index) {
      const entries = EMOJI_DATA.map((e) => ({
        name: e.emoji,
        label: e.label,
        categories: [],
        keywords: e.tags,
        variants: e.skins
      }));
      index = { entries, categories: [] };
    }
    return Promise.resolve(index);
  },
  makeIcon(entry, variants) {
    const tone = variants.emojiSkinTone ?? 0;
    const value = tone >= 1 && tone <= 5 ? entry.variants?.[tone - 1] ?? entry.name : entry.name;
    return { type: "emoji", value };
  },
  cacheVariant() {
    return "";
  }
};

